-- MSC Articleship Program v3 (course msc-articleship-program). Generated by msc-content/articleship-program/v3/build/lms/build_lms_sql.mjs
-- from lms-rows.json; do not edit by hand. Rows follow V3-STRUCTURE section 2 (one session per Day, Day 0 to Day 6) with
-- Padam's B9 sheets, minus row 1.6 Work Simulation (release 2). Files live in bucket articleship-program-resources under articleship-program-v3/.
--
-- 002 · Release 1: the course as seven sessions with the 37 rows that are ready now.
-- Run after: every file in upload-release-1/ is in the bucket at the same path (uploads-manifest.csv, release 1).
-- The preflight below stops the whole file, changing nothing, if any of those files is missing.
-- What it does: updates title, description and resources of sessions 1-7 (inserts any that are missing) and removes
-- v2's six second sessions (video_number 8-13), so the course shows one session per Day. Never touches recordings
-- (industrial_training_path), enrolment, schema or storage.
-- Rows flagged "copy": true open in the copyable reader (/ca-resource/read/); "copy": "browser" opens the browser's own
-- PDF viewer instead (the fallback, a data change only).
-- Reversible: restore the export taken first:
--   SELECT * FROM public.videos WHERE course = 'msc-articleship-program' ORDER BY day_number, video_number;
-- Afterwards, 003 adds the later rows as their files arrive; 004 adds the Automail row.
BEGIN;

DO $preflight$
DECLARE
    missing text;
BEGIN
    SELECT string_agg(p.path, E'\n' ORDER BY p.path) INTO missing
    FROM unnest(ARRAY[
        'articleship-program-v3/day-0/MSC Articleship Guidebook.pdf',
        'articleship-program-v3/day-1/Choose your CV.pdf',
        'articleship-program-v3/day-1/The Nothing CV.pdf',
        'articleship-program-v3/day-1/CV templates.pdf',
        'articleship-program-v3/day-1/Keywords by domain.pdf',
        'articleship-program-v3/day-1/Cover letters.pdf',
        'articleship-program-v3/day-1/Cover letters.docx',
        'articleship-program-v3/day-2/Big 10 articleship routes.pdf',
        'articleship-program-v3/day-2/Big 10 Mail IDs.xlsx',
        'articleship-program-v3/day-2/Citywise Firm Email IDs.xlsx',
        'articleship-program-v3/day-2/Articleship Cold Mailing List - All Emails.xlsx',
        'articleship-program-v3/day-2/Application templates.pdf',
        'articleship-program-v3/day-2/Follow-up templates.pdf',
        'articleship-program-v3/day-2/Back-out templates.pdf',
        'articleship-program-v3/day-3/LinkedIn search links.pdf',
        'articleship-program-v3/day-3/Career Portal Links.xlsx',
        'articleship-program-v3/day-3/Connection notes.pdf',
        'articleship-program-v3/day-3/First message after the request is accepted.pdf',
        'articleship-program-v3/day-3/Follow-up messages.pdf',
        'articleship-program-v3/day-3/Follow-up list.xlsx',
        'articleship-program-v3/day-4/Master Excel test.xlsx',
        'articleship-program-v3/day-5/Top 100 Articleship Firms.xlsx',
        'articleship-program-v3/day-6/Articleship registration process.pdf',
        'articleship-program-v3/day-6/Articleship transfer guidelines.pdf',
        'articleship-program-v3/day-6/Industrial training guide.pdf',
        'articleship-program-v3/day-6/CA Final study guidelines.pdf',
        'articleship-program-v3/day-6/Post Articleship CVs.pdf'
    ]::text[]) AS p(path)
    WHERE NOT EXISTS (
        SELECT 1 FROM storage.objects AS o WHERE o.bucket_id = 'articleship-program-resources' AND o.name = p.path
    );
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'Upload these files to bucket articleship-program-resources first (nothing was changed):%', E'\n' || missing;
    END IF;
END
$preflight$;

